s=s[:a]+"""const i=bot.inventory.items().filter(i=>i.name==='stone_pickaxe'&&i.durabilityUsed<131).sort((a,b)=>b.durabilityUsed-a.durabilityUsed)[0];if(i)await bot.equip(i,'hand');else await bot.unequip('hand');await tick(2);const price=i?1500:(b.name==='tuff'||b.name==='stone_bricks'?8200:b.name==='basalt'?7000:18000);if(Date.now()+price>1792272430000)throw Error('CUT_DEADLINE');"""+s[b:]
extras=r'''
const soft=['tuff','stone_bricks','basalt','end_stone','cobbled_deepslate'],walls=['cobbled_deepslate','end_stone','stone_bricks','tuff','basalt'];
async function verticalUp(topFinal=false){const p=life.position.floored();if(!life.onGround||!closed(p))throw Error("UP_PRE_FULL");const incoming=Object.values(bot.entities).find(e=>(e.name==="dragon_fireball"&&e.position.distanceTo(life.position)<12));if(incoming)throw Error("CURRENT_INCOMING_FIREBALL");await put(p.offset(0,3,0),topFinal?['end_stone',...soft]:soft);for(const[x,z]of[[1,0],[-1,0],[0,1],[0,-1]])await put(p.offset(x,2,z),walls);await cut(p.offset(0,2,0));const block=soft.map(n=>bot.inventory.items().find(i=>i.name===n)).find(Boolean);if(!block)throw Error("FLOOR_INPUT");await bot.equip(block,"hand");await tick(2);await bot.lookAt(p.offset(.5,-.1,.5),true);stop();bot.setControlState("jump",true);let high=false;for(let n=0;n<12;n++){await tick();if(life.position.y>=p.y+1.02){high=true;break}}if(!high)throw Error("JUMP_CLEARANCE");await bot.placeBlock(bot.blockAt(p.offset(0,-1,0)),V(0,1,0));await tick(1);if(!full(p))throw Error("FLOOR_ACK");stop();for(let n=0;n<25&&!life.onGround;n++)await tick();if(!life.onGround||Math.abs(life.position.y-p.y-1)>.12||!closed(p.offset(0,1,0)))throw Error("UP_POST_FULL");trace.push(["VERTICAL_UP_FULL",life.position.clone(),bot.health,caps()]);}
async function softDown(minY){mode="escape";stop();for(let k=0;k<25&&!life.onGround;k++)await tick();for(let n=0;n<50&&life.position.floored().y>minY;n++){const p=life.position.floored();await cut(p.offset(0,-1,0));for(let k=0;k<22;k++){await tick();if(life.onGround&&life.position.y<p.y-.8)break}if(!life.onGround||Math.abs(life.position.y-p.y+1)>.12)throw Error("DOWN_POST");await put(life.position.floored().offset(0,2,0),soft);trace.push(["SOFT_DOWN_FULL",life.position.clone(),bot.health])}}
function surfaceY(x,z){for(let y=68;y>=52;y--)if(full(V(x,y-1,z))&&air(V(x,y,z))&&air(V(x,y+1,z)))return y;return null}
'''
