body=r'''
let reached=false,surfacePath=[];
try{check();const g=global.P1RangedStairs17;if(!g?.dryReturn||g.lifeId!==life.id||!life.position.floored().equals(V(28,49,-20)))throw Error("BASE_LIFE");const nodes=g.nodes.slice(0,7).map(a=>V(...a));for(const q of nodes.slice(1)){const p=life.position.floored();await put(q.offset(0,-1,0),walls);for(const z of[-1,1])for(const y of[0,1])await put(q.offset(0,y,z),walls);await put(q.offset(0,2,0),soft);await cut(p.offset(0,2,0));await cut(q.offset(0,1,0));await cut(q);await move(q)}await cover();const sy=surfaceY(22,-20);if(sy===null||sy>62)throw Error("SURFACE_HEIGHT_"+sy);while(life.position.y<sy-.1)await verticalUp();trace.push(["ACTUAL_EXIT_COLUMN",sy,life.position.clone(),bot.health]);const source=life.position.floored(),targetY=surfaceY(30,24);if(targetY===null)throw Error("TARGET_SURFACE");const target=V(30,targetY,24),key=q=>q.toArray().join(","),queue=[source],seen=new Map([[key(source),null]]);let found=null;for(let n=0;n<queue.length&&n<4500;n++){const a=queue[n];if(a.equals(target)){found=a;break}for(const[x,z]of[[0,1],[1,0],[-1,0],[0,-1]])for(const dy of[0,1,-1]){const q=a.offset(x,dy,z);if(q.x<18||q.x>34||q.z< -23||q.z>27||q.y<52||q.y>65||seen.has(key(q))||!full(q.offset(0,-1,0))||!air(q)||!air(q.offset(0,1,0))||cloudAt(q.offset(.5,0,.5)))continue;seen.set(key(q),a);queue.push(q);break}}if(!found)throw Error("NO_NATIVE_SURFACE_PATH");for(let q=found;q;q=seen.get(key(q)))surfacePath.push(q);surfacePath.reverse();for(let j=1;j<surfacePath.length;j++){const q=surfacePath[j],p=life.position.floored();if(q.y>p.y)await cut(p.offset(0,2,0));await cut(q.offset(0,1,0));await cut(q);await move(q)}await cover();reached=true;global.P1LastCage18={lifeId:life.id,dimension,base:life.position.floored().toArray(),at:Date.now()};
}catch(e){issue=e.message}finally{mode="escape";if(!lost)try{await cover()}catch(e){endingIssue=e.message}finish()}return{...snapshot(),reached,surfacePath:surfacePath.map(q=>q.toArray())};
'''
